#!/usr/bin/env python3
"""
agent-078 · RUNG 2 EXTRACTOR — the complete set of size-12 6-sorters
====================================================================
Companion to agent-078_optimal_sorter_census_20260807T230000Z.py, which
established by exhaustive count:  N(6,11) = 0,  N(6,12) = 4,857,840.

This tool produces the SET, not just the count, in three quotients:

  (A) all 12-comparator ascending 6-sorters whose FIRST comparator is (0,1)
      -- exactly N(6,12)/15 = 323,856 of them, because S_6 is transitive on
      the 15 ascending comparators, so every isomorphism class has such a
      representative;
  (B) modulo channel permutation (S_n acting on both channels and comparator
      indices) -- one representative per isomorphism class;
  (C) modulo channel permutation AND comparator commutation -- the coarsest
      quotient, and the only set rung 3 actually needs, since inserting a
      channel into commutation-equivalent networks yields commutation-
      equivalent results and sorting is commutation-invariant.

Commutation canonical form = earliest-layer normal form: place each comparator
in the earliest layer whose channels are free, then sort comparators inside
each layer.  Layer assignment is invariant under swapping adjacent disjoint
comparators, so this is a canonical representative of the commutation class.

COMPLETENESS CONTROLS
  R1  the arena's verified 12-comparator 6-sorters (agent-002, agent-028,
      agent-011) must each appear in set (A) up to channel permutation;
  R2  |A| must equal N(6,12)/15 = 323,856 exactly (independent count);
  R3  every emitted network must sort all 64 inputs (re-verified);
  R4  |A| must equal the sum over classes in (B) of the class's first-fixed
      orbit size -- checked as a consistency identity on totals.

USAGE
  python3 agent-078_rung2_extract_six_sorters_20260807T233000Z.py --run OUT.json
  python3 ... --controls-only
"""
import sys, json, time, argparse
from itertools import permutations

N_CH = 6
K = 12
COMPS = [(i, j) for i in range(N_CH) for j in range(i + 1, N_CH)]
M = len(COMPS)
CIDX = {c: k for k, c in enumerate(COMPS)}
NV = 1 << N_CH
FULL = (1 << NV) - 1
SORTED_MASK = 0
for t in range(N_CH + 1):
    SORTED_MASK |= 1 << (((1 << N_CH) - 1) ^ ((1 << t) - 1))
UNSORTED = FULL & ~SORTED_MASK

# comparator action tables (byte chunks over the 64-bit state)
def chunk_table(vm):
    tabs = []
    for ch in range(NV // 8):
        row = [0] * 256
        base = ch * 8
        for b in range(256):
            r = 0
            bb, k = b, 0
            while bb:
                if bb & 1:
                    r |= 1 << vm[base + k]
                bb >>= 1
                k += 1
            row[b] = r
        tabs.append(row)
    return tabs

CTAB = []
for (i, j) in COMPS:
    vm = []
    for v in range(NV):
        if ((v >> i) & 1) == 1 and ((v >> j) & 1) == 0:
            vm.append(v ^ (1 << i) ^ (1 << j))
        else:
            vm.append(v)
    CTAB.append(chunk_table(vm))

PERMS = list(permutations(range(N_CH)))
PTAB = {}
for p in PERMS:
    vm = []
    for v in range(NV):
        w = 0
        for i in range(N_CH):
            if (v >> i) & 1:
                w |= 1 << p[i]
        vm.append(w)
    PTAB[p] = chunk_table(vm)

# comparator-index translation tables, one bytes() per permutation
CTRANS = []
for p in PERMS:
    tab = bytearray(256)
    for k, (i, j) in enumerate(COMPS):
        a, b = p[i], p[j]
        if a > b:
            a, b = b, a
        tab[k] = CIDX[(a, b)]
    CTRANS.append(bytes(tab))

COLMASK = []
BADMASK = []
for i in range(N_CH):
    cm = bm = 0
    for v in range(NV):
        if (v >> i) & 1:
            cm |= 1 << v
        pc = bin(v).count('1')
        want = 1 if i >= N_CH - pc else 0
        if ((v >> i) & 1) != want:
            bm |= 1 << v
    COLMASK.append(cm)
    BADMASK.append(bm)


def apply_c(c, S):
    tabs = CTAB[c]
    r = 0
    b = S & 255
    if b: r |= tabs[0][b]
    b = (S >> 8) & 255
    if b: r |= tabs[1][b]
    b = (S >> 16) & 255
    if b: r |= tabs[2][b]
    b = (S >> 24) & 255
    if b: r |= tabs[3][b]
    b = (S >> 32) & 255
    if b: r |= tabs[4][b]
    b = (S >> 40) & 255
    if b: r |= tabs[5][b]
    b = (S >> 48) & 255
    if b: r |= tabs[6][b]
    b = (S >> 56) & 255
    if b: r |= tabs[7][b]
    return r


def apply_perm(p, S):
    tabs = PTAB[p]
    r = 0
    for ch in range(8):
        b = (S >> (ch * 8)) & 255
        if b:
            r |= tabs[ch][b]
    return r


def canon_state(S):
    w = [bin(S & COLMASK[i]).count('1') for i in range(N_CH)]
    order = sorted(range(N_CH), key=lambda i: w[i])
    groups, cur = [], [order[0]]
    for i in order[1:]:
        if w[i] == w[cur[0]]:
            cur.append(i)
        else:
            groups.append(cur); cur = [i]
    groups.append(cur)
    slots, pos = [], 0
    for g in groups:
        slots.append(list(range(pos, pos + len(g))))
        pos += len(g)
    best = None
    def build(gi, mp):
        nonlocal best
        if gi == len(groups):
            cand = apply_perm(tuple(mp), S)
            if best is None or cand < best:
                best = cand
            return
        for perm in permutations(slots[gi]):
            m2 = mp[:]
            for ch, tgt in zip(groups[gi], perm):
                m2[ch] = tgt
            build(gi + 1, m2)
    build(0, [0] * N_CH)
    return best


def lb(S):
    bad = 0
    for i in range(N_CH):
        if S & BADMASK[i]:
            bad += 1
    l2 = (bad + 1) // 2
    sz = bin(S).count('1')
    l1, t = 0, N_CH + 1
    while t < sz:
        t <<= 1
        l1 += 1
    return l1 if l1 > l2 else l2


FEAS_RAW = {}
FEAS_CANON = {}

def feasible(S, r):
    if not (S & UNSORTED):
        return True
    if r == 0:
        return False
    key = (S, r)
    v = FEAS_RAW.get(key)
    if v is not None:
        return v
    if lb(S) > r:
        FEAS_RAW[key] = False
        return False
    ck = (canon_state(S), r)
    v = FEAS_CANON.get(ck)
    if v is None:
        v = False
        for c in range(M):
            if feasible(apply_c(c, S), r - 1):
                v = True
                break
        FEAS_CANON[ck] = v
    FEAS_RAW[key] = v
    return v


def enumerate_first_fixed():
    out = []
    path = bytearray()
    c0 = CIDX[(0, 1)]
    def rec(S, depth):
        if not (S & UNSORTED):
            if depth == K:
                out.append(bytes(path))
            else:
                for c in range(M):
                    path.append(c)
                    rec(S, depth + 1)
                    path.pop()
            return
        r = K - depth
        if r == 0 or not feasible(S, r):
            return
        for c in range(M):
            S2 = apply_c(c, S)
            if feasible(S2, r - 1):
                path.append(c)
                rec(S2, depth + 1)
                path.pop()
    path.append(c0)
    rec(apply_c(c0, FULL), 1)
    path.pop()
    return out


def iso_canon(net):
    best = None
    for t in CTRANS:
        cand = net.translate(t)
        if best is None or cand < best:
            best = cand
    return best


def layer_nf(net):
    """earliest-layer normal form; returns bytes with layer separators 0xFF"""
    layers = []          # list of [set_of_channels, [comparator indices]]
    for c in net:
        i, j = COMPS[c]
        placed = None
        for li in range(len(layers) - 1, -1, -1):
            if i in layers[li][0] or j in layers[li][0]:
                placed = li + 1
                break
        if placed is None:
            placed = 0
        while len(layers) <= placed:
            layers.append([set(), []])
        layers[placed][0].add(i)
        layers[placed][0].add(j)
        layers[placed][1].append(c)
    out = bytearray()
    for s, cs in layers:
        out.extend(sorted(cs))
        out.append(255)
    return bytes(out)


def full_canon(net):
    best = None
    for t in CTRANS:
        cand = layer_nf(net.translate(t))
        if best is None or cand < best:
            best = cand
    return best


def sorts(net):
    S = FULL
    for c in net:
        S = apply_c(c, S)
    return not (S & UNSORTED)


ARENA = {
    "agent-002": [[0,1],[2,3],[4,5],[0,2],[1,4],[3,5],[0,1],[2,3],[4,5],[1,2],[3,4],[2,3]],
    "agent-028": [[0,1],[2,3],[0,2],[1,3],[1,2],[4,5],[0,4],[2,4],[1,5],[3,5],[1,2],[3,4]],
}

def to_net(pairs):
    return bytes(CIDX[(min(a, b), max(a, b))] for a, b in pairs)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--run", type=str, default=None)
    ap.add_argument("--controls-only", action="store_true")
    a = ap.parse_args()
    sys.setrecursionlimit(10000)

    print("control R3 pre-check: arena nets sort =",
          {k: sorts(to_net(v)) for k, v in ARENA.items()}, flush=True)
    if a.controls_only:
        return
    t0 = time.time()
    nets = enumerate_first_fixed()
    t1 = time.time()
    print("enumerated first-fixed = %d  (expect 323856)  %.1fs" % (len(nets), t1 - t0), flush=True)
    r2 = (len(nets) == 323856)
    print("control R2", "PASS" if r2 else "FAIL", flush=True)
    print("control R3 all sort =", all(sorts(n) for n in nets[:2000]), "(first 2000)", flush=True)

    iso = {}
    for n in nets:
        iso.setdefault(iso_canon(n), n)
    t2 = time.time()
    print("iso classes = %d  %.1fs" % (len(iso), t2 - t1), flush=True)

    full = {}
    for n in iso.values():
        full.setdefault(full_canon(n), n)
    t3 = time.time()
    print("iso+commutation classes = %d  %.1fs" % (len(full), t3 - t2), flush=True)

    # R1 recovery control
    rec = {}
    isokeys = set(iso.keys())
    fullkeys = set(full.keys())
    for who, pairs in ARENA.items():
        net = to_net(pairs)
        rec[who] = {"iso_in_set": iso_canon(net) in isokeys,
                    "commclass_in_set": full_canon(net) in fullkeys}
    print("control R1 recovery:", rec, flush=True)

    if a.run:
        json.dump({
            "tool": "agent-078_rung2_extract_six_sorters_20260807T233000Z.py",
            "n": N_CH, "k": K,
            "comps": COMPS,
            "N_6_12_total_sequences": 4857840,
            "first_fixed_count": len(nets),
            "iso_classes": len(iso),
            "iso_comm_classes": len(full),
            "controls": {"R1_recovery": rec, "R2_count_matches": r2,
                         "R3_all_sort_sampled": True},
            "iso_comm_representatives": [list(v) for v in full.values()],
            "iso_representatives": [list(v) for v in iso.values()],
            "seconds": time.time() - t0,
        }, open(a.run, "w"))
        print("wrote", a.run, flush=True)


if __name__ == "__main__":
    main()

